// Escape needs a real `on:keydown` listener on the element: a delegated
// `onKeyDown` runs only after the event reached the document, where the page's
// own Escape listeners already are.
import { For, Show, createSignal, createEffect, on, onMount } from 'solid-js';
import type { JSX } from 'solid-js';
import { expandIri } from '../../model/edit.js';
import { curie } from '../../model/parse.js';
import { reducedMotion, text } from '../../stores/view.js';
import { restoreReaderSpot } from '../list/scroll-anchor.js';
import { Button } from './button.jsx';
import './edit.css';

export type FieldHook = { openEdit: () => void };

type InputEl = HTMLInputElement | HTMLTextAreaElement;

export function focusWithoutJump(el: HTMLElement | null | undefined): void {
  if (!el) return;
  restoreReaderSpot();
  try { el.focus({ preventScroll: true }); } catch { el.focus(); }
  if (typeof el.scrollIntoView === 'function') {
    // `nearest` moves as little as possible, and what it does move it eases —
    // a cursor that lands off screen is worse than a movement, a HARD jump is
    // worse than both. A reader who asked for less motion gets it instantly.
    el.scrollIntoView({
      block: 'nearest', inline: 'nearest',
      behavior: reducedMotion() ? 'auto' : 'smooth',
    });
  }
}

function Input(props: {
  start: string;
  multiline?: boolean;
  type?: 'text' | 'date';
  hint?: string;
  validate?: (fresh: string) => boolean;
  opOpslaan: (fresh: string) => void;
  opAnnuleer: () => void;
  report: (el: InputEl) => void;
}): JSX.Element {
  let el!: InputEl;
  // Removing the field from the DOM fires a synchronous blur on it, so without
  // these two flags Escape still saves and `save()` runs twice.
  let cancelled = false;
  let handled = false;

  function save(): void {
    if (cancelled || handled) return;
    const fresh = el.value;
    if (props.validate && !props.validate(fresh)) {
      el.setAttribute('aria-invalid', 'true');
      return;
    }
    handled = true;
    props.opOpslaan(fresh);
  }

  function cancel(): void {
    cancelled = true;
    props.opAnnuleer();
  }

  const onKey = (e: KeyboardEvent) => {
    if (e.key === 'Escape') {
      e.preventDefault();
      e.stopPropagation();
      cancel();
      return;
    }
    if (e.key !== 'Enter') return;
    if (props.multiline && !(e.ctrlKey || e.metaKey)) return;
    e.preventDefault();
    save();
  };

  onMount(() => {
    props.report(el);
    focusWithoutJump(el);
  });

  return (
    <Show
      when={props.multiline}
      fallback={(
        <input
          ref={(n) => { el = n; }}
          type={props.type === 'date' ? 'date' : 'text'}
          class="edit-input inline-field-input"
          placeholder={props.hint || undefined}
          value={props.start}
          on:keydown={onKey}
          on:blur={() => save()}
        />
      )}
    >
      <textarea
        ref={(n) => { el = n; }}
        class="edit-input inline-field-input"
        placeholder={props.hint || undefined}
        value={props.start}
        on:keydown={onKey}
        on:blur={() => save()}
      />
    </Show>
  );
}

export function InlineField(props: {
  value?: string;
  multiline?: boolean;
  type?: 'text' | 'date';
  hint?: string;
  startValue?: string;
  empty?: () => JSX.Element;
  validate?: (fresh: string) => boolean;
  onSave?: (fresh: string) => void;
  onCancel?: () => void;
  onOpen?: () => void;
  withoutPencil?: boolean;
  hook?: (api: FieldHook) => void;
}): JSX.Element {
  const [local, setLocal] = createSignal(props.value ?? '');
  createEffect(on(() => props.value, (v) => setLocal(v ?? ''), { defer: true }));
  const [open, setOpen] = createSignal(false);
  let field: InputEl | undefined;

  const openEdit = () => {
    if (open()) { focusWithoutJump(field); return; }
    setOpen(true);
  };
  props.hook?.({ openEdit });

  return (
    <span class="inline-field">
      <Show
        when={open()}
        fallback={(
          <>
            <Show
              when={local()}
              fallback={(
                <Show when={props.empty} fallback={<span class="inline-field-hint">{props.hint}</span>}>
                  {(l) => l()()}
                </Show>
              )}
            >
              <span class="inline-field-value">{local()}</span>
            </Show>
            <Show when={!props.withoutPencil}>
              <Button
                label="✎"
                cls="inline-field-edit"
                ariaLabel={text('edit.editField')}
                onClick={openEdit}
              />
            </Show>
          </>
        )}
      >
        <Input
          start={local() || props.startValue || ''}
          multiline={props.multiline}
          type={props.type}
          hint={props.hint}
          validate={props.validate}
          report={(el) => { field = el; props.onOpen?.(); }}
          opOpslaan={(fresh) => {
            setLocal(fresh);
            setOpen(false);
            field = undefined;
            props.onSave?.(fresh);
          }}
          opAnnuleer={() => {
            setOpen(false);
            field = undefined;
            props.onCancel?.();
          }}
        />
      </Show>
    </span>
  );
}

export type IriOption = { iri: string; label: string; curie?: string; extra?: string };

export function optionText(options: IriOption[], iri?: string | null): string {
  if (!iri) return '';
  const o = options.find((x) => x.iri === iri);
  if (o) return o.label;
  return (curie(iri) as string) || iri;
}

export const SUGGESTION_CAP = 50;

export function filterSuggestions(options: IriOption[], input: string,
  cap: number = SUGGESTION_CAP): IriOption[] {
  const q = String(input || '').trim().toLowerCase();
  const hits = q
    ? options.filter((o) => o.label.toLowerCase().includes(q)
      || (o.curie || '').toLowerCase().includes(q)
      || (o.extra || '').toLowerCase().includes(q)
      || o.iri.toLowerCase().includes(q))
    : options;
  return hits.length > cap ? hits.slice(0, cap) : hits;
}

function caption(o: IriOption): string {
  const c = o.curie && o.curie !== o.label ? o.curie : '';
  return [c, o.extra || ''].filter(Boolean).join(' · ');
}

let datalistCounter = 0;

export function IriCombobox(props: {
  options: IriOption[];
  value?: string;
  placeholder?: string;
  listId?: string;
  ariaLabel?: string;
  onPick?: (iri: string) => void;
  onOpen?: () => void;
  hook?: (api: FieldHook & { value: () => string }) => void;
}): JSX.Element {
  datalistCounter += 1;
  const ownId = `iri-dl-${datalistCounter}`;
  const id = () => props.listId || ownId;
  let input!: HTMLInputElement;
  const [typed, setTyped] = createSignal('');
  const visible = () => filterSuggestions(props.options, typed());

  const currentValue = () => {
    const inv = input.value;
    const exact = props.options.find((o) => o.label === inv);
    return exact ? exact.iri : (expandIri(inv) as string);
  };

  const openEdit = () => {
    focusWithoutJump(input);
    if (input && input.isConnected && document.activeElement === input) props.onOpen?.();
  };
  props.hook?.({ openEdit, value: currentValue });

  let accepted = props.value ?? '';

  return (
    <span class="iri-combobox">
      <input
        ref={(n) => { input = n; }}
        type="text"
        list={id()}
        placeholder={props.placeholder || text('edit.iriPlaceholder')}
        aria-label={props.ariaLabel}
        class="edit-input iri-combobox-input"
        value={props.value ?? ''}
        on:keydown={(e: KeyboardEvent) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            return;
          }
          if (e.key !== 'Escape') return;
          e.preventDefault();
          e.stopPropagation();
          input.value = accepted;
        }}
        on:input={() => setTyped(input.value)}
        on:change={() => {
          accepted = input.value;
          props.onPick?.(currentValue());
        }}
      />
      <Show when={!props.listId}>
        <datalist id={ownId}>
          <For each={visible()}>{(o) => (
            <option value={o.label} label={caption(o) || undefined} />
          )}</For>
        </datalist>
      </Show>
    </span>
  );
}
