import type { JSX } from 'solid-js';
import './edit.css';

export function Button(props: {
  label: string;
  onClick: (e?: Event) => void;
  cls?: string;
  ariaLabel?: string;
  title?: string;
}): JSX.Element {
  return (
    <button
      type="button"
      class={['edit-button', props.cls || ''].filter(Boolean).join(' ')}
      title={props.title}
      aria-label={props.ariaLabel}
      on:click={(e: MouseEvent) => {
        e.preventDefault();
        e.stopPropagation();
        props.onClick(e);
      }}
    >{props.label}</button>
  );
}

export function Editbar(props: { children?: JSX.Element }): JSX.Element {
  return <span class="editbar">{props.children}</span>;
}
